vulnerable_code:
use Illuminate\Support\Facades\Broadcast;
use App\Models\User;

// routes/channels.php
Broadcast::channel('home.{homeId}.sensors', function (User $user, int $homeId) {
    // Insecure presence callback: merely checks that the user is logged in
    return !is_null($user);
});

corrected_code:
use Illuminate\Support\Facades\Broadcast;
use App\Models\User;

// routes/channels.php
Broadcast::channel('home.{homeId}.sensors', function (User $user, int $homeId) {
    return $user->homes()
        ->where('homes.id', $homeId)
        ->exists();
});
